<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { healthAiApi, type AdminUser } from "@/api/healthai";
defineOptions({ name: "HealthAiUsers" });
const rows = ref<AdminUser[]>([]); const keyword = ref(""); const role = ref(""); const loading = ref(true); const error = ref("");
const filtered = computed(() => rows.value.filter(row => (!keyword.value || row.name.includes(keyword.value) || row.id.includes(keyword.value)) && (!role.value || row.role === role.value)));
const formatTime = (value: string | null) => value ? new Date(value).toLocaleDateString("zh-CN") : "—";
onMounted(async () => { try { rows.value = await healthAiApi.listUsers([]); } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } });
</script>
<template><div class="page"><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb" /><el-card shadow="never" v-loading="loading"><template #header><div class="bar"><b>用户与客户</b><el-button @click="keyword = ''; role = ''">清空筛选</el-button></div></template><div class="toolbar"><el-input v-model="keyword" clearable placeholder="姓名或用户 ID" style="width:260px" /><el-select v-model="role" placeholder="用户角色" clearable style="width:150px"><el-option label="客户" value="customer" /><el-option label="健管师" value="consultant" /></el-select></div><el-empty v-if="!filtered.length" description="暂无用户资料" /><el-table v-else :data="filtered" stripe><el-table-column prop="name" label="姓名" /><el-table-column prop="role" label="角色"><template #default="{row}">{{ row.role === 'customer' ? '客户' : '健管师' }}</template></el-table-column><el-table-column prop="consultant" label="主责健管师"><template #default="{row}">{{ row.consultant || '—' }}</template></el-table-column><el-table-column label="健康资料"><template #default="{row}">{{ row.reportCount }} 份报告 · {{ row.observationCount }} 项指标</template></el-table-column><el-table-column prop="status" label="状态" /><el-table-column prop="createdAt" label="资料时间"><template #default="{row}">{{ formatTime(row.createdAt) }}</template></el-table-column></el-table></el-card></div></template>
<style scoped>.page{padding:4px}.bar,.toolbar{display:flex;align-items:center;justify-content:space-between}.toolbar{justify-content:flex-start;gap:12px;margin-bottom:16px}.mb{margin-bottom:16px}</style>
